// Source of truth: logic/scoring.js (unit tested in tests/scoring.test.js).
const SCORING_WEIGHTS = {
  has_business_email: 15,
  company_size_11_50: 10,
  company_size_51_200: 15,
  company_size_200_plus: 20,
  budget_stated: 20,
  timeline_under_30d: 15,
  requested_call: 20,
  replied_within_1h: 10,
  competitor_page_view: 10,
  free_email_domain: -10,
  student_or_jobseeker: -25,
  outside_service_area: -15
};

const SCORE_BANDS = [
  { name: 'hot', min: 60 },
  { name: 'warm', min: 35 },
  { name: 'cold', min: 15 },
  { name: 'junk', min: 0 }
];

const FREE_EMAIL_DOMAINS = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','proton.me','protonmail.com','gmx.com','mail.com'];

function bandFor(score) {
  for (const b of SCORE_BANDS) { if (score >= b.min) return b.name; }
  return 'junk';
}

function scoreLead(l) {
  const reasons = [];
  let raw = 0;
  const add = (sig) => {
    const pts = SCORING_WEIGHTS[sig];
    if (typeof pts !== 'number') return;
    raw += pts;
    reasons.push(sig + ' ' + (pts > 0 ? '+' : '') + pts);
  };
  const email = typeof l.email === 'string' ? l.email.trim().toLowerCase() : '';
  const domain = email.includes('@') ? email.split('@').pop() : '';
  const free = domain !== '' && FREE_EMAIL_DOMAINS.includes(domain);
  if (email && !free) add('has_business_email');
  if (free) add('free_email_domain');
  const size = Number(l.company_size);
  if (Number.isFinite(size)) {
    if (size >= 200) add('company_size_200_plus');
    else if (size >= 51) add('company_size_51_200');
    else if (size >= 11) add('company_size_11_50');
  }
  if (l.budget_stated === true || Number(l.budget_amount) > 0) add('budget_stated');
  const days = Number(l.timeline_days);
  if (Number.isFinite(days) && days > 0 && days <= 30) add('timeline_under_30d');
  if (l.requested_call === true) add('requested_call');
  if (l.replied_within_minutes !== undefined && Number(l.replied_within_minutes) <= 60) add('replied_within_1h');
  if (l.viewed_competitor_page === true) add('competitor_page_view');
  if (l.is_student === true || l.is_jobseeker === true) add('student_or_jobseeker');
  if (l.in_service_area === false) add('outside_service_area');
  const score = Math.max(0, Math.min(100, raw));
  return { score, band: bandFor(score), reasons };
}

return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  const s = scoreLead(lead);
  return { json: Object.assign({}, item.json, {
    lead: Object.assign({}, lead, { score: s.score, band: s.band, score_reasons: s.reasons })
  }) };
});

// Return value for the caller. Keep the shape stable - three workflows read it.
const scored = $('Score Lead').all();
return scored.map((item) => ({ json: {
  lead: item.json.lead,
  score: item.json.lead.score,
  band: item.json.lead.band,
  reasons: item.json.lead.score_reasons,
  rubric_version: $('Load Rubric Config').first().json.rubric_version
} }));
